/**
 * @name SSRF via URL handling
 * @description URL parsing could lead to Server-Side Request Forgery
 * @kind problem
 * @problem.severity error
 * @id py/ssrf
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.ApiGraphs
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources

module SsrfConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Network requests via urllib or similar
    sink = API::moduleImport("urllib").getMember(["request", "urlopen"]).getACall().getArg(0) or
    sink = API::moduleImport("httplib").getMember("HTTPConnection").getACall().getArg(0) or
    sink = API::moduleImport("http").getMember("client").getMember("HTTPConnection").getACall().getArg(0) or
    sink = API::moduleImport("aiohttp").getMember("ClientSession").getACall().getArg(0)
  }
}

module SsrfFlow = TaintTracking::Global<SsrfConfig>;

from DataFlow::Node source, DataFlow::Node sink
where SsrfFlow::flow(source, sink)
select sink, "SSRF vulnerability: user input flows to network request"

/**
 * @name Open redirect via user-controlled URLs
 * @description User input could create URLs that lead to open redirect vulnerabilities
 * @kind path-problem
 * @problem.severity high
 * @id py/open-redirect
 * @tags security
 *        external/cwe/cwe-601
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module OpenRedirectConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // URL construction in yarl library
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("yarl").getMember("URL").getACall() and
      sink = call.getArg(0)
    )
  }
}

module OpenRedirectFlow = TaintTracking::Global<OpenRedirectConfig>;
import OpenRedirectFlow::PathGraph

from OpenRedirectFlow::PathNode source, OpenRedirectFlow::PathNode sink
where OpenRedirectFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Open redirect vulnerability: user input flows into URL construction at $@.", source.getNode(), "user input"
